function createObjective(levelId, slot, kind, target) {
	const id = `c${levelId}_m${slot}`;
	switch (kind) {
		case "nearMiss": return {
			id,
			kind,
			target,
			title: `${target} Yakın Geçiş (Makas) yap`,
			shortLabel: `${target} Makas`
		};
		case "maxSpeed": return {
			id,
			kind,
			target,
			title: `${target} km/s hıza ulaş`,
			shortLabel: `${target} km/s`
		};
		case "driftPoints": return {
			id,
			kind,
			target,
			title: `${target.toLocaleString("tr-TR")} Drift puanı topla`,
			shortLabel: `${target.toLocaleString("tr-TR")} Drift`
		};
		case "runGold": return {
			id,
			kind,
			target,
			title: `Yoldan ${target} Altın topla`,
			shortLabel: `${target} Altın`
		};
		case "cleanCurves": return {
			id,
			kind,
			target,
			title: `${target} virajı temiz geç`,
			shortLabel: `${target} Viraj`
		};
		case "minIntegrity": return {
			id,
			kind,
			target,
			title: target >= 100 ? "Hiç hasar almadan bitir (%100)" : `Gövde sağlığı %${target}+ kalsın`,
			shortLabel: target >= 100 ? "Hasarsız" : `%${target}+ Gövde`
		};
		case "score": return {
			id,
			kind,
			target,
			title: `${target.toLocaleString("tr-TR")} puan topla`,
			shortLabel: `${target.toLocaleString("tr-TR")} Puan`
		};
		case "maxCombo": return {
			id,
			kind,
			target,
			title: `×${target} Kombo çarpanına ulaş`,
			shortLabel: `×${target} Kombo`
		};
		case "timeLimit": return {
			id,
			kind,
			target,
			title: `${target} saniye içinde bitir`,
			shortLabel: `≤${target} sn`
		};
		case "roadEvents": return {
			id,
			kind,
			target,
			title: `${target} Rampa / Turbo şeridi kullan`,
			shortLabel: `${target} Rampa/Turbo`
		};
	}
}
function roundTo(val, step) {
	return Math.max(step, Math.round(val / step) * step);
}
function buildTargetForKind(kind, levelId, targetDist) {
	const t = (levelId - 1) / 99;
	switch (kind) {
		case "nearMiss": return Math.min(26, Math.max(2, Math.round(2 + t * 18)));
		case "maxSpeed": return roundTo(145 + t * 185, 5);
		case "driftPoints": return roundTo(220 + t * 2400, 50);
		case "runGold": return Math.min(35, Math.max(4, Math.round(4 + t * 22)));
		case "cleanCurves": return Math.min(8, Math.max(1, Math.round(1 + t * 5.2)));
		case "minIntegrity":
			if (levelId <= 12) return 75;
			if (levelId <= 35) return 80;
			if (levelId <= 65) return 85;
			if (levelId % 5 === 0) return 100;
			return 90;
		case "score": return roundTo(targetDist * (1.85 + t * 2.4), 250);
		case "maxCombo":
			if (levelId <= 12) return 2;
			if (levelId <= 38) return 3;
			if (levelId <= 72) return 4;
			return 5;
		case "timeLimit": {
			const rawSec = targetDist / (35 + t * 31);
			return Math.max(18, Math.round(rawSec));
		}
		case "roadEvents": return Math.min(5, Math.max(1, Math.round(1 + t * 3)));
	}
}
var OBJECTIVE_PAIRS = [
	["nearMiss", "maxSpeed"],
	["runGold", "minIntegrity"],
	["score", "nearMiss"],
	["driftPoints", "maxSpeed"],
	["timeLimit", "nearMiss"],
	["cleanCurves", "runGold"],
	["maxCombo", "score"],
	["nearMiss", "minIntegrity"],
	["driftPoints", "timeLimit"],
	["score", "maxCombo"],
	["roadEvents", "maxSpeed"],
	["runGold", "nearMiss"],
	["cleanCurves", "minIntegrity"],
	["timeLimit", "score"],
	["driftPoints", "maxCombo"]
];
function buildCareerLevels() {
	const levels = [];
	for (let id = 1; id <= 100; id++) {
		const chapterIndex = Math.min(3, Math.floor((id - 1) / 25));
		const localIdx = (id - 1) % 25;
		const chapter = CAREER_CHAPTERS[chapterIndex];
		const isMilestone = id % 10 === 0;
		const t = (id - 1) / 99;
		const targetDistanceMeters = roundTo(650 + Math.pow(t, 1.08) * 2800 + (isMilestone ? 200 : 0), 50);
		let atmosphere = "golden";
		if (chapterIndex === 0) atmosphere = localIdx % 6 === 4 ? "mist" : localIdx % 7 === 5 ? "night" : localIdx % 9 === 8 ? "rainy" : "golden";
		else if (chapterIndex === 1) atmosphere = localIdx % 5 === 3 ? "night" : localIdx % 8 === 6 ? "mist" : "golden";
		else if (chapterIndex === 2) atmosphere = localIdx % 3 === 0 ? "mist" : localIdx % 3 === 1 ? "night" : "rainy";
		else atmosphere = localIdx % 4 === 0 ? "night" : localIdx % 4 === 2 ? "mist" : localIdx % 7 === 6 ? "rainy" : "golden";
		let roadRule = "classic";
		if (id >= 12 && (id % 5 === 0 || chapterIndex === 1 && localIdx % 4 === 1)) roadRule = "twoway";
		if (id >= 20 && (id % 10 === 0 || chapterIndex >= 2 && localIdx % 6 === 4)) roadRule = "pursuit";
		if (id === 100) {
			roadRule = "pursuit";
			atmosphere = "night";
		}
		let pair = OBJECTIVE_PAIRS[(id - 1) % OBJECTIVE_PAIRS.length];
		if (id === 1) pair = ["runGold", "nearMiss"];
		else if (id === 2) pair = ["maxSpeed", "minIntegrity"];
		else if (id === 3) pair = ["nearMiss", "score"];
		const m1 = createObjective(id, 1, pair[0], buildTargetForKind(pair[0], id, targetDistanceMeters));
		const m2 = createObjective(id, 2, pair[1], buildTargetForKind(pair[1], id, targetDistanceMeters));
		const milestoneMult = isMilestone ? 1.65 : 1;
		const finishGold = roundTo((75 + t * 340) * milestoneMult, 5);
		const missionGold = roundTo((40 + t * 180) * milestoneMult, 5);
		const perfectBonusGold = roundTo((50 + t * 240) * milestoneMult, 5);
		const finishXp = roundTo((120 + t * 1250) * milestoneMult, 10);
		const replayGold = roundTo(20 + t * 65, 5);
		levels.push({
			id,
			chapterIndex,
			title: CHAPTER_TITLES[chapterIndex]?.[localIdx] || `Bölüm ${id}`,
			biome: chapter.biome,
			atmosphere,
			roadRule,
			targetDistanceMeters,
			isMilestone,
			missions: [m1, m2],
			rewards: {
				finishGold,
				mission1Gold: missionGold,
				mission2Gold: missionGold,
				perfectBonusGold,
				finishXp,
				replayGold
			}
		});
	}
	return levels;
}
var CAREER_LEVELS = buildCareerLevels();
function getCareerLevelById(levelId) {
	return CAREER_LEVELS[Math.max(1, Math.min(100, Math.floor(levelId))) - 1];
}
function evaluateCareerObjective(spec, metrics) {
	let current = 0;
	let completed = false;
	let progressText = "";
	switch (spec.kind) {
		case "nearMiss":
			current = Math.floor(metrics.nearMissCount);
			completed = current >= spec.target;
			progressText = `${Math.min(current, spec.target)}/${spec.target}`;
			break;
		case "maxSpeed":
			current = Math.round(metrics.peakSpeedKmh);
			completed = current >= spec.target;
			progressText = `${current}/${spec.target} km/s`;
			break;
		case "driftPoints":
			current = Math.round(metrics.driftPoints);
			completed = current >= spec.target;
			progressText = `${Math.min(current, spec.target).toLocaleString("tr-TR")}/${spec.target.toLocaleString("tr-TR")}`;
			break;
		case "runGold":
			current = Math.floor(metrics.runGold);
			completed = current >= spec.target;
			progressText = `${Math.min(current, spec.target)}/${spec.target}`;
			break;
		case "cleanCurves":
			current = Math.floor(metrics.cleanCurvesCount);
			completed = current >= spec.target;
			progressText = `${Math.min(current, spec.target)}/${spec.target}`;
			break;
		case "minIntegrity":
			current = Math.round(metrics.integrityPercent);
			completed = current >= spec.target;
			progressText = `%${current} / %${spec.target}`;
			break;
		case "score":
			current = Math.floor(metrics.score);
			completed = current >= spec.target;
			progressText = `${Math.min(current, spec.target).toLocaleString("tr-TR")}/${spec.target.toLocaleString("tr-TR")}`;
			break;
		case "maxCombo":
			current = Math.floor(metrics.maxCombo);
			completed = current >= spec.target;
			progressText = `×${Math.min(current, spec.target)}/×${spec.target}`;
			break;
		case "timeLimit":
			current = Math.round(metrics.elapsedSec * 10) / 10;
			completed = metrics.elapsedSec <= spec.target;
			progressText = `${Math.ceil(metrics.elapsedSec)}/${spec.target} sn`;
			break;
		case "roadEvents":
			current = Math.floor(metrics.roadEventsCount);
			completed = current >= spec.target;
			progressText = `${Math.min(current, spec.target)}/${spec.target}`;
	}
	return {
		spec,
		current,
		target: spec.target,
		completed,
		progressText
	};
}
var CAREER_STORAGE_KEY = "viraj_career_progress_v1";
var CareerProgressManager = class {
	constructor() {
		this.highestUnlockedLevel = 1;
		this.levels = {};
		this.claimedChests = /* @__PURE__ */ new Set();
		this.load();
	}
	load() {
		try {
			const raw = localStorage.getItem(CAREER_STORAGE_KEY);
			if (!raw) return;
			const parsed = JSON.parse(raw);
			if (typeof parsed.highestUnlockedLevel === "number" && Number.isFinite(parsed.highestUnlockedLevel)) this.highestUnlockedLevel = Math.max(1, Math.min(100, Math.floor(parsed.highestUnlockedLevel)));
			if (parsed.levels && typeof parsed.levels === "object") for (const [k, v] of Object.entries(parsed.levels)) {
				const id = Number(k);
				if (Number.isInteger(id) && id >= 1 && id <= 100 && v && typeof v === "object") this.levels[id] = {
					stars: Math.max(0, Math.min(3, Math.floor(v.stars || 0))),
					mission1Done: Boolean(v.mission1Done),
					mission2Done: Boolean(v.mission2Done),
					bestScore: Math.max(0, Math.floor(v.bestScore || 0)),
					bestTimeSec: Math.max(0, Number(v.bestTimeSec || 0))
				};
			}
			if (Array.isArray(parsed.claimedChests)) {
				for (const s of parsed.claimedChests) if (typeof s === "number" && Number.isFinite(s)) this.claimedChests.add(s);
			}
		} catch {}
	}
	save() {
		try {
			const payload = {
				highestUnlockedLevel: this.highestUnlockedLevel,
				levels: this.levels,
				claimedChests: Array.from(this.claimedChests)
			};
			localStorage.setItem(CAREER_STORAGE_KEY, JSON.stringify(payload));
		} catch {}
	}
	isLevelUnlocked(levelId) {
		return levelId >= 1 && levelId <= this.highestUnlockedLevel;
	}
	getSnapshot() {
		let totalStars = 0;
		let completedLevelsCount = 0;
		const levelsCopy = {};
		for (const [k, v] of Object.entries(this.levels)) {
			const id = Number(k);
			levelsCopy[id] = { ...v };
			totalStars += v.stars;
			if (v.stars >= 1) completedLevelsCount++;
		}
		return {
			highestUnlockedLevel: this.highestUnlockedLevel,
			totalStars,
			maxStars: 300,
			completedLevelsCount,
			levels: levelsCopy,
			claimedChests: Array.from(this.claimedChests)
		};
	}
	recordVictory(level, metrics) {
		const m1 = evaluateCareerObjective(level.missions[0], metrics);
		const m2 = evaluateCareerObjective(level.missions[1], metrics);
		const runStars = 1 + (m1.completed ? 1 : 0) + (m2.completed ? 1 : 0);
		const prev = this.levels[level.id] || {
			stars: 0,
			mission1Done: false,
			mission2Done: false,
			bestScore: 0,
			bestTimeSec: 0
		};
		const isFirstClear = prev.stars === 0;
		const newlyClearedM1 = m1.completed && !prev.mission1Done;
		const newlyClearedM2 = m2.completed && !prev.mission2Done;
		const mergedM1 = prev.mission1Done || m1.completed;
		const mergedM2 = prev.mission2Done || m2.completed;
		const newBestStars = Math.max(prev.stars, 1 + (mergedM1 ? 1 : 0) + (mergedM2 ? 1 : 0));
		const newlyPerfect = newBestStars === 3 && prev.stars < 3;
		const finishGold = isFirstClear ? level.rewards.finishGold : 0;
		const mission1Gold = newlyClearedM1 ? level.rewards.mission1Gold : 0;
		const mission2Gold = newlyClearedM2 ? level.rewards.mission2Gold : 0;
		const perfectBonusGold = newlyPerfect ? level.rewards.perfectBonusGold : 0;
		const replayGold = !isFirstClear ? level.rewards.replayGold : 0;
		const rewardGoldAwarded = finishGold + mission1Gold + mission2Gold + perfectBonusGold + replayGold;
		const rewardXpAwarded = isFirstClear ? level.rewards.finishXp : Math.round(level.rewards.finishXp * .35);
		this.levels[level.id] = {
			stars: newBestStars,
			mission1Done: mergedM1,
			mission2Done: mergedM2,
			bestScore: Math.max(prev.bestScore, Math.floor(metrics.score)),
			bestTimeSec: prev.bestTimeSec > 0 ? Math.min(prev.bestTimeSec, metrics.elapsedSec) : metrics.elapsedSec
		};
		let nextLevelUnlocked = null;
		if (level.id < 100 && this.highestUnlockedLevel <= level.id) {
			this.highestUnlockedLevel = level.id + 1;
			nextLevelUnlocked = this.highestUnlockedLevel;
		}
		this.save();
		return {
			levelId: level.id,
			levelTitle: level.title,
			won: true,
			starsEarned: runStars,
			previousBestStars: prev.stars,
			isFirstClear,
			nextLevelUnlocked,
			mission1: m1,
			mission2: m2,
			elapsedSec: metrics.elapsedSec,
			targetDistanceMeters: level.targetDistanceMeters,
			rewardGoldAwarded,
			rewardXpAwarded,
			rewardBreakdown: {
				finishGold,
				mission1Gold,
				mission2Gold,
				perfectBonusGold,
				replayGold
			}
		};
	}
	buildDefeatOutcome(level, metrics) {
		const prev = this.levels[level.id];
		const m1 = evaluateCareerObjective(level.missions[0], metrics);
		const m2 = evaluateCareerObjective(level.missions[1], metrics);
		return {
			levelId: level.id,
			levelTitle: level.title,
			won: false,
			starsEarned: 0,
			previousBestStars: prev?.stars || 0,
			isFirstClear: false,
			nextLevelUnlocked: null,
			mission1: m1,
			mission2: m2,
			elapsedSec: metrics.elapsedSec,
			targetDistanceMeters: level.targetDistanceMeters,
			rewardGoldAwarded: 0,
			rewardXpAwarded: 0,
			rewardBreakdown: {
				finishGold: 0,
				mission1Gold: 0,
				mission2Gold: 0,
				perfectBonusGold: 0,
				replayGold: 0
			}
		};
	}
	claimStarChest(starsRequired) {
		const chest = CAREER_STAR_CHESTS.find((c) => c.starsRequired === starsRequired);
		if (!chest) return {
			ok: false,
			rewardGold: 0,
			title: ""
		};
		if (this.claimedChests.has(starsRequired)) return {
			ok: false,
			rewardGold: 0,
			title: chest.title
		};
		if (this.getSnapshot().totalStars < starsRequired) return {
			ok: false,
			rewardGold: 0,
			title: chest.title
		};
		this.claimedChests.add(starsRequired);
		this.save();
		return {
			ok: true,
			rewardGold: chest.rewardGold,
			title: chest.title
		};
	}
};
