function getMaxNitroCapacity(nitroTankLevel) {
	return 100 + Math.max(0, nitroTankLevel) * 25;
}
function getDefaultPowerUpUpgrades() {
	return {
		nitro: {
			primary: 0,
			secondary: 0
		},
		repair: {
			primary: 0,
			secondary: 0
		},
		magnet: {
			primary: 0,
			secondary: 0
		},
		rampage: {
			primary: 0,
			secondary: 0
		}
	};
}
function clampPowerUpLevel(level) {
	return Math.max(0, Math.min(5, Math.floor(level || 0)));
}
function getNitroPickupSpeedBonusKmh(level) {
	return clampPowerUpLevel(level) * 6;
}
function getNitroPickupFreeBurnSec(level) {
	return clampPowerUpLevel(level) * 1;
}
function getRepairHealRatio(level) {
	return [
		.45,
		.55,
		.65,
		.76,
		.88,
		1
	][clampPowerUpLevel(level)];
}
function getMagnetDurationSec(level) {
	return 10 + clampPowerUpLevel(level) * 2;
}
function getMagnetRangeMeters(level) {
	return 34 + clampPowerUpLevel(level) * 8;
}
function getRampageDurationSec(level) {
	return Number((3.5 + clampPowerUpLevel(level) * .5).toFixed(1));
}
function getRampageSpeedMultiplier(level) {
	return Number((2 + clampPowerUpLevel(level) * .15).toFixed(2));
}
function formatSpeedMultiplier(mult) {
	return `${mult.toFixed(2).replace(/\.00$/, "").replace(/(\.\d)0$/, "$1")}×`;
}
