function getTuningClassForUpgrades(upgrades) {
	const total = (upgrades.engine || 0) + (upgrades.tires || 0) + (upgrades.nitroTank || 0) + (upgrades.nitroPower || 0);
	const max = 16;
	if (total >= 15) return {
		total,
		max,
		label: "Pro Spec",
		textClass: "text-rose-300",
		barClass: "bg-gradient-to-r from-amber-400 via-orange-400 to-rose-500"
	};
	if (total >= 11) return {
		total,
		max,
		label: "Yarış",
		textClass: "text-amber-300",
		barClass: "bg-amber-400"
	};
	if (total >= 6) return {
		total,
		max,
		label: "Modifiye",
		textClass: "text-sky-300",
		barClass: "bg-sky-400"
	};
	if (total >= 1) return {
		total,
		max,
		label: "Cadde",
		textClass: "text-emerald-300",
		barClass: "bg-emerald-400"
	};
	return {
		total,
		max,
		label: "Standart",
		textClass: "text-zinc-300",
		barClass: "bg-zinc-400"
	};
}
