var WORLD_WIDTH = 1600;
function generateSceneryProps(coords, mapWidth) {
	const props = [];
	for (let i = 0; i < coords.length; i++) {
		const levelId = i + 1;
		const chapterIndex = Math.min(3, Math.floor(i / 25));
		const pt = coords[i];
		const leftSpace = pt.x - 58;
		const rightSpace = mapWidth - (pt.x + 58);
		if (leftSpace > 38) {
			const lx = Math.max(20, leftSpace * (.28 + levelId * 37 % 52 / 100));
			const ly = pt.y + (levelId * 19 % 50 - 25);
			props.push({
				id: `p_l_${levelId}`,
				x: lx,
				y: ly,
				scale: .78 + levelId * 13 % 38 / 100,
				chapterIndex,
				variant: levelId * 5 % 6,
				flip: levelId % 2 === 0
			});
			if (leftSpace > 128 && levelId % 2 === 0) {
				const lx2 = Math.max(18, lx - 48 + levelId * 11 % 24);
				const ly2 = pt.y + (levelId % 4 === 0 ? -44 : 44);
				props.push({
					id: `p_l2_${levelId}`,
					x: lx2,
					y: ly2,
					scale: .64 + levelId * 7 % 26 / 100,
					chapterIndex,
					variant: (levelId + 3) % 6,
					flip: true
				});
			}
		}
		if (rightSpace > 38) {
			const rx = Math.min(mapWidth - 20, pt.x + 62 + rightSpace * (.24 + levelId * 53 % 54 / 100));
			const ry = pt.y + (levelId * 29 % 52 - 26);
			props.push({
				id: `p_r_${levelId}`,
				x: rx,
				y: ry,
				scale: .78 + levelId * 23 % 38 / 100,
				chapterIndex,
				variant: (levelId * 7 + 2) % 6,
				flip: levelId % 2 === 1
			});
			if (rightSpace > 128 && levelId % 2 === 1) {
				const rx2 = Math.min(mapWidth - 18, rx + 44 - levelId * 17 % 22);
				const ry2 = pt.y + (levelId % 3 === 0 ? -46 : 46);
				props.push({
					id: `p_r2_${levelId}`,
					x: rx2,
					y: ry2,
					scale: .64 + levelId * 11 % 24 / 100,
					chapterIndex,
					variant: (levelId + 4) % 6,
					flip: false
				});
			}
		}
	}
	return props;
}
function generateRoadsideBeacons(coords) {
	const beacons = [];
	const palette = [
		"#fcd34d",
		"#fb923c",
		"#38bdf8",
		"#fb7185"
	];
	for (let i = 1; i < coords.length; i += 3) {
		const pt = coords[i];
		const prev = coords[i - 1];
		const side = pt.x - prev.x >= 0 ? -1 : 1;
		const chapterIndex = Math.min(3, Math.floor(i / 25));
		beacons.push({
			id: `b_${i}`,
			x: pt.x + side * 44,
			y: pt.y + 38,
			color: palette[chapterIndex]
		});
	}
	return beacons;
}
function generateWideFlankLandmarks(mapHeight) {
	const items = [];
	const rows = 96;
	for (let r = 0; r < rows; r++) {
		const t = (r + .5) / rows;
		const y = t * mapHeight;
		const chapterIndex = t >= .74 ? 0 : t >= .49 ? 1 : t >= .24 ? 2 : 3;
		const lx = 42 + r * 149 % 496;
		items.push({
			id: `wf_l_${r}`,
			x: lx,
			y: y + (r * 31 % 62 - 31),
			scale: .92 + r * 19 % 68 / 100,
			chapterIndex,
			variant: r % 6
		});
		const rx = 1052 + r * 173 % 496;
		items.push({
			id: `wf_r_${r}`,
			x: rx,
			y: y + (r * 47 % 62 - 31),
			scale: .92 + r * 29 % 68 / 100,
			chapterIndex,
			variant: (r + 3) % 6
		});
	}
	return items;
}
function generateTerrainPatches(coords, mapWidth) {
	const patches = [];
	for (let i = 0; i < coords.length; i++) {
		const levelId = i + 1;
		const chapterIndex = Math.min(3, Math.floor(i / 25));
		const pt = coords[i];
		const leftSpace = pt.x - 44;
		const rightSpace = mapWidth - (pt.x + 44);
		if (leftSpace > 30) patches.push({
			id: `tp_l_${levelId}`,
			x: Math.max(24, leftSpace * (.42 + levelId * 23 % 36 / 100)),
			y: pt.y + (levelId * 17 % 46 - 23),
			rx: 28 + levelId * 13 % 32,
			ry: 16 + levelId * 7 % 18,
			rot: levelId * 19 % 36 - 18,
			chapterIndex,
			tone: levelId % 2
		});
		if (rightSpace > 30) patches.push({
			id: `tp_r_${levelId}`,
			x: Math.min(mapWidth - 24, pt.x + 46 + rightSpace * (.28 + levelId * 41 % 44 / 100)),
			y: pt.y + (levelId * 29 % 46 - 23),
			rx: 28 + levelId * 11 % 32,
			ry: 16 + levelId * 13 % 18,
			rot: levelId * 23 % 36 - 18,
			chapterIndex,
			tone: (levelId + 1) % 2
		});
	}
	return patches;
}
function generateMicroFoliage(coords, mapWidth) {
	const details = [];
	for (let i = 0; i < coords.length; i++) {
		const chapterIndex = Math.min(3, Math.floor(i / 25));
		const p1 = coords[i];
		const p2 = coords[Math.min(coords.length - 1, i + 1)];
		const samples = [{
			x: p1.x,
			y: p1.y,
			seed: (i + 1) * 31
		}, {
			x: (p1.x + p2.x) * .5,
			y: (p1.y + p2.y) * .5,
			seed: (i + 1) * 67 + 19
		}];
		for (let sIdx = 0; sIdx < samples.length; sIdx++) {
			const sample = samples[sIdx];
			const seed = sample.seed;
			const leftEdge = sample.x - 42;
			const rightEdge = sample.x + 42;
			if (leftEdge > 22) {
				const lx1 = Math.max(10, leftEdge - 8 - seed * 13 % Math.max(14, Math.floor(leftEdge - 14)));
				const ly1 = sample.y + (seed * 7 % 38 - 19);
				details.push({
					id: `mf_l1_${i}_${sIdx}`,
					x: lx1,
					y: ly1,
					scale: .72 + seed * 11 % 44 / 100,
					chapterIndex,
					variant: seed % 6,
					flip: seed % 2 === 0
				});
				if (leftEdge > 92) {
					const lx2 = Math.max(12, 12 + seed * 29 % Math.max(18, Math.floor(leftEdge - 48)));
					const ly2 = sample.y + (seed * 19 % 46 - 23);
					details.push({
						id: `mf_l2_${i}_${sIdx}`,
						x: lx2,
						y: ly2,
						scale: .68 + seed * 17 % 42 / 100,
						chapterIndex,
						variant: (seed + 2) % 6,
						flip: seed % 3 === 0
					});
				}
			}
			const rightSpace = mapWidth - rightEdge;
			if (rightSpace > 22) {
				const rx1 = Math.min(mapWidth - 10, rightEdge + 8 + seed * 23 % Math.max(14, Math.floor(rightSpace - 14)));
				const ry1 = sample.y + (seed * 11 % 38 - 19);
				details.push({
					id: `mf_r1_${i}_${sIdx}`,
					x: rx1,
					y: ry1,
					scale: .72 + seed * 13 % 44 / 100,
					chapterIndex,
					variant: (seed + 3) % 6,
					flip: seed % 2 === 1
				});
				if (rightSpace > 92) {
					const rx2 = Math.min(mapWidth - 12, rightEdge + 38 + seed * 37 % Math.max(18, Math.floor(rightSpace - 48)));
					const ry2 = sample.y + (seed * 23 % 46 - 23);
					details.push({
						id: `mf_r2_${i}_${sIdx}`,
						x: rx2,
						y: ry2,
						scale: .68 + seed * 19 % 42 / 100,
						chapterIndex,
						variant: (seed + 5) % 6,
						flip: seed % 3 === 1
					});
				}
			}
		}
	}
	return details;
}
