			ctx.lineWidth = 6;
			ctx.lineCap = "round";
			ctx.beginPath();
			ctx.moveTo(sx, 78);
			ctx.bezierCurveTo(sx + dir * 55, 165, sx + dir * 18, 285, sx + dir * 74, 418);
			ctx.stroke();
			ctx.lineWidth = 3.5;
			ctx.beginPath();
			ctx.moveTo(sx + dir * 32, 168);
			ctx.lineTo(sx + dir * 82, 206);
			ctx.moveTo(sx + dir * 38, 294);
			ctx.lineTo(sx + dir * 88, 330);
