			blueTrim.position.set(side * (bodyWidth * .515), .28, .04);
			chassisGroup.add(blueTrim);
			const canard = new Mesh(canardGeo, mats.carbon);
			canard.position.set(side * (bodyWidth * .49), .34, -2.04);
			canard.rotation.x = .28;
			canard.rotation.z = side * -.2;
			chassisGroup.add(canard);
