			red.position.set(tx + side * .08, tailY, rearZ + .015);
			chassisGroup.add(red);
			const amb = new Mesh(trackGeo(new BoxGeometry(.11, .075, .04)), mats.amber);
			amb.position.set(tx - side * .11, tailY + .028, rearZ + .015);
			chassisGroup.add(amb);
			const rev = new Mesh(trackGeo(new BoxGeometry(.11, .055, .04)), mats.reverseLight);
			rev.position.set(tx - side * .11, tailY - .036, rearZ + .015);
