			const count = shiftLedMats.length;
			const flashRedline = rpmRatio > .93 && Math.floor(timeSec * 14) % 2 === 0;
			const litCount = Math.round(MathUtils.clamp((rpmRatio - .35) / .62, 0, 1) * count);
			for (let i = 0; i < count; i++) {
				const lit = i < litCount;
				if (flashRedline) shiftLedMats[i].color.setHex(15680580);
				else if (!lit) shiftLedMats[i].color.setHex(2042167);
				else if (i < Math.floor(count * .45)) shiftLedMats[i].color.setHex(2278750);
				else if (i < Math.floor(count * .78)) shiftLedMats[i].color.setHex(16096779);
				else shiftLedMats[i].color.setHex(15680580);
			}
