function createDailyMissionFromTemplate(tpl, tier, dateKey, slotIdx) {
	const target = tpl.baseTarget + tier * tpl.stepTarget;
	const rewardGold = tpl.baseReward + tier * tpl.stepReward;
	return {
		id: `daily_${dateKey}_${slotIdx}_${tpl.key}`,
		templateKey: tpl.key,
		metric: tpl.metric,
		mode: tpl.mode,
		tier,
		title: tpl.titleForTarget(target),
		target,
		progress: 0,
		rewardGold,
		completed: false,
		claimed: false
	};
}
