	armL.translate(0, .78, 0);
	armL.rotateZ(.22);
	armL.translate(-.62, 1.85, 0);
	parts.push(armL);
	const elbowL = new CylinderGeometry(.21, .22, .72, 6);
	elbowL.rotateZ(Math.PI / 2);
	elbowL.translate(-.34, 1.92, 0);
	parts.push(elbowL);
