		const idx = MathUtils.clamp(Math.round((lookS - firstS) / 4), 0, this.samples.length - 1);
		const k = this.samples[idx].curvature;
		if (k < -.017) return "sharp-left";
		if (k > .017) return "sharp-right";
		if (k < -.0085) return "left";
		if (k > .0085) return "right";
