			positions[pBase + 1] = v0.y;
			positions[pBase + 2] = v0.z;
			positions[pBase + 3] = v1.x;
			positions[pBase + 4] = v1.y;
			positions[pBase + 5] = v1.z;
			const uBase = i * 4;
			const vCoord = s.s / vScale;
			uvs[uBase] = flipU ? 1 : 0;
			uvs[uBase + 1] = vCoord;
			uvs[uBase + 2] = flipU ? 0 : 1;
			uvs[uBase + 3] = vCoord;
