	createTunnelArchGeometry(startIndex, count, radiusX, radiusY, flipNormals) {
		const segs = 12;
		const cols = 13;
		const positions = new Float32Array(count * cols * 3);
		const uvs = new Float32Array(count * cols * 2);
		const indices = [];
		const p = new Vector3();
		for (let i = 0; i < count; i++) {
			const s = this.getSample(startIndex + i);
			const vCoord = s.s / 12;
			for (let j = 0; j < cols; j++) {
				const u = j / segs;
				const theta = Math.PI * (1 - u);
				const lx = Math.cos(theta) * radiusX;
				const ly = Math.max(-.2, Math.sin(theta) * radiusY);
				p.copy(s.pos).addScaledVector(s.right, lx).addScaledVector(s.normal, ly);
				const idx3 = (i * cols + j) * 3;
				positions[idx3] = p.x;
				positions[idx3 + 1] = p.y;
				positions[idx3 + 2] = p.z;
				const idx2 = (i * cols + j) * 2;
				uvs[idx2] = u;
				uvs[idx2 + 1] = vCoord;
			}
			if (i < count - 1) for (let j = 0; j < segs; j++) {
				const a = i * cols + j;
				const b = a + 1;
				const c = (i + 1) * cols + j;
				const d = c + 1;
				if (flipNormals) {
					indices.push(a, c, b);
					indices.push(b, c, d);
				} else {
					indices.push(a, b, c);
					indices.push(b, d, c);
				}
			}
		}
		const geo = new BufferGeometry();
		geo.setAttribute("position", new BufferAttribute(positions, 3));
		geo.setAttribute("uv", new BufferAttribute(uvs, 2));
		geo.setIndex(indices);
		geo.computeVertexNormals();
		return geo;
	}
