			if (this.phase !== "garage") this.camera.clearViewOffset();
			this.camera.updateProjectionMatrix();
			this.basePixelRatio = this.isSoftwareGl ? 1 : Math.min(window.devicePixelRatio || 1, this.isMobileDevice ? 2 : 1.75);
			const dprMult = this.perfTier === 0 ? 1 : this.perfTier === 1 ? .9 : .8;
			const minDpr = this.isMobileDevice ? Math.min(this.basePixelRatio, 1.5) : 1;
			this.currentPixelRatio = this.isSoftwareGl ? 1 : Math.max(minDpr, Math.min(this.basePixelRatio, Number((this.basePixelRatio * dprMult).toFixed(2))));
