	unlockCar(id) {
		const spec = CAR_MODELS.find((m) => m.id === id);
		if (!spec) return false;
		if (this.unlockedCars.has(id)) {
			this.setCarModel(id);
			return true;
		}
		if (this.totalGold < spec.priceGold) return false;
		this.audio.init();
		this.totalGold -= spec.priceGold;
		this.unlockedCars.add(id);
		this.equippedCarModel = id;
		this.saveProgression();
		this.setCarModel(id);
		this.audio.playCarUnlock();
		this.handleMissionRewards(this.missions.recordPeak("carsUnlocked", this.unlockedCars.size));
		this.notifyProgression();
		this.pushHud(true);
		return true;
	}
	grantRewardGold(amount, label = "Ödül Altın") {
		const safe = Math.max(0, Math.floor(amount));
		if (safe <= 0) return this.totalGold;
		this.audio.init();
		this.totalGold += safe;
		this.saveProgression();
		this.audio.playUpgrade();
		this.notifyProgression();
		this.emitCallout(label, `+${safe} Altın`, "amber");
		this.pushHud(true);
		return this.totalGold;
	}
	grantRewardXp(amount) {
		const safe = Math.max(0, Math.floor(amount));
		if (safe <= 0) return;
		this.audio.init();
		const prevLevel = this.getLivePlayerLevel().level;
		this.lifetimeXp += safe;
		this.saveProgression();
		this.audio.playUpgrade();
		const nextInfo = this.getLivePlayerLevel();
		this.lastKnownLevel = Math.max(this.lastKnownLevel, nextInfo.level);
		this.handleMissionRewards(this.missions.recordPeak("playerLevel", nextInfo.level));
		this.notifyProgression();
		this.emitCallout("Bonus XP!", `+${safe} Puan`, "cyan");
		if (nextInfo.level > prevLevel) this.callbacks.onLevelUp?.({
			fromLevel: prevLevel,
			toLevel: nextInfo.level,
			rankTitle: nextInfo.rankTitle,
			totalXp: nextInfo.totalXp
		});
		this.pushHud(true);
	}
	claimLevelRoadReward(level) {
		const safeLevel = Math.floor(level);
		const reward = getLevelRoadReward(safeLevel);
		if (!reward) return {
			ok: false,
			reward: null,
			goldAdded: 0
		};
		if (this.getLivePlayerLevel().level < safeLevel || this.claimedLevelRewards.has(safeLevel)) return {
			ok: false,
			reward,
			goldAdded: 0
		};
		this.audio.init();
		this.claimedLevelRewards.add(safeLevel);
		let goldAdded = 0;
		let crateTierId;
		if (reward.kind === "gold" && reward.goldAmount) {
			this.totalGold += reward.goldAmount;
			goldAdded += reward.goldAmount;
		} else if (reward.kind === "powerup_unlock") {
			if (reward.bonusGold && reward.bonusGold > 0) {
				this.totalGold += reward.bonusGold;
				goldAdded += reward.bonusGold;
			}
		} else if (reward.kind === "car_color" && reward.carColorId) {
			this.unlockedCarColors.add(reward.carColorId);
			if (reward.bonusGold && reward.bonusGold > 0) {
				this.totalGold += reward.bonusGold;
				goldAdded += reward.bonusGold;
			}
		} else if (reward.kind === "visual" && reward.visualCategory && reward.visualItemId) {
			const info = this.getVisualUnlockSetAndPrice(reward.visualCategory, reward.visualItemId);
			if (info) info.set.add(reward.visualItemId);
			if (reward.bonusGold && reward.bonusGold > 0) {
				this.totalGold += reward.bonusGold;
				goldAdded += reward.bonusGold;
			}
		} else if (reward.kind === "crate" && reward.crateTierId) crateTierId = reward.crateTierId;
		this.saveProgression();
		this.notifyProgression();
		this.pushHud(true);
		return {
			ok: true,
			reward,
			goldAdded,
			crateTierId
		};
	}
	claimAllLevelRoadRewards() {
		const currentLevel = Math.min(100, this.getLivePlayerLevel().level);
		let claimedCount = 0;
		let totalGoldAdded = 0;
		const unlockedCosmetics = [];
		const pendingCrates = [];
		for (let lv = 1; lv <= currentLevel; lv++) {
			if (this.claimedLevelRewards.has(lv)) continue;
			const res = this.claimLevelRoadReward(lv);
			if (!res.ok || !res.reward) continue;
			claimedCount++;
			totalGoldAdded += res.goldAdded;
			if (res.crateTierId) pendingCrates.push(res.crateTierId);
			else if (res.reward.kind === "car_color" || res.reward.kind === "visual" || res.reward.kind === "powerup_unlock") unlockedCosmetics.push(res.reward.title);
		}
		return {
			claimedCount,
			totalGoldAdded,
			unlockedCosmetics,
			pendingCrates
		};
	}
	grantCarUnlocked(id, equip = false) {
		const spec = CAR_MODELS.find((m) => m.id === id);
		if (!spec) return {
			newlyUnlocked: false,
			duplicateGold: 0
		};
		this.audio.init();
		if (this.unlockedCars.has(id)) {
			const comp = Math.max(300, Math.round(spec.priceGold * .6));
			this.totalGold += comp;
			this.saveProgression();
			this.audio.playUpgrade();
			this.notifyProgression();
			this.pushHud(true);
			return {
				newlyUnlocked: false,
				duplicateGold: comp
			};
		}
		this.unlockedCars.add(id);
		if (equip) {
			this.equippedCarModel = id;
			this.setCarModel(id);
		}
		this.saveProgression();
		this.audio.playCarUnlock();
		this.handleMissionRewards(this.missions.recordPeak("carsUnlocked", this.unlockedCars.size));
		this.notifyProgression();
		this.pushHud(true);
		return {
			newlyUnlocked: true,
			duplicateGold: 0
		};
	}
