			localStorage.setItem(CAR_WHEELS_KEY, JSON.stringify(this.carWheels));
			localStorage.setItem(UNLOCKED_KITS_KEY, JSON.stringify(Array.from(this.unlockedBodyKits)));
			localStorage.setItem(UNLOCKED_SPOILERS_KEY, JSON.stringify(Array.from(this.unlockedSpoilers)));
			localStorage.setItem(UNLOCKED_LIVERIES_KEY, JSON.stringify(Array.from(this.unlockedLiveries)));
