async function triggerGoogleRewardedAd(placement, onAudioPause, onAudioResume) {
	if (Capacitor.isNativePlatform()) return triggerNativeRewardedAd(onAudioPause, onAudioResume);
	const ready = await initGoogleAds(true);
	const adBreakFn = window.adBreak;
	if (!ready || !adBreakFn) return {
		outcome: "unavailable",
		provider: "fallback_required"
	};
	return new Promise((resolve) => {
		let settled = false;
		let viewed = false;
		let dismissed = false;
		let rewardOffered = false;
		const finish = (result) => {
			if (settled) return;
			settled = true;
			window.clearTimeout(guardTimer);
			onAudioResume();
			resolve(result);
		};
		const guardTimer = window.setTimeout(() => {
			finish({
				outcome: "unavailable",
				provider: "fallback_required"
			});
		}, 6500);
		try {
			adBreakFn({
				type: "reward",
				name: placement.kind,
				beforeAd: () => {
					window.clearTimeout(guardTimer);
					onAudioPause();
				},
				beforeReward: (showAdFn) => {
					rewardOffered = true;
					window.clearTimeout(guardTimer);
					showAdFn();
				},
				adViewed: () => {
					viewed = true;
				},
				adDismissed: () => {
					dismissed = true;
				},
				afterAd: () => {
					onAudioResume();
				},
				adBreakDone: (info) => {
					if (viewed || info?.breakStatus === "viewed") finish({
						outcome: "viewed",
						provider: "google"
					});
					else if (dismissed || info?.breakStatus === "dismissed") finish({
						outcome: "dismissed",
						provider: "google"
					});
					else if (!rewardOffered || info?.breakStatus === "notReady" || info?.breakStatus === "noAdPreloaded" || info?.breakStatus === "timeout" || info?.breakStatus === "error") finish({
						outcome: "unavailable",
						provider: "fallback_required"
					});
					else finish({
						outcome: "unavailable",
						provider: "fallback_required"
					});
				}
			});
		} catch {
			finish({
				outcome: "unavailable",
				provider: "fallback_required"
			});
		}
	});
}
async function triggerGoogleInterstitialAd(placementName, onAudioPause, onAudioResume) {
	if (Capacitor.isNativePlatform()) return triggerNativeInterstitialAd(onAudioPause, onAudioResume);
	const ready = await initGoogleAds(true);
	const adBreakFn = window.adBreak;
	if (!ready || !adBreakFn) return {
		outcome: "unavailable",
		provider: "fallback_required"
	};
	return new Promise((resolve) => {
		let settled = false;
		let adDisplayed = false;
		const finish = (result) => {
			if (settled) return;
			settled = true;
			window.clearTimeout(guardTimer);
			onAudioResume();
			resolve(result);
		};
		const guardTimer = window.setTimeout(() => {
			finish({
				outcome: "unavailable",
				provider: "fallback_required"
			});
		}, 4500);
		try {
			adBreakFn({
				type: "next",
				name: placementName,
				beforeAd: () => {
					adDisplayed = true;
					window.clearTimeout(guardTimer);
					onAudioPause();
				},
				afterAd: () => {
					onAudioResume();
				},
				adBreakDone: (info) => {
					if (adDisplayed || info?.breakStatus === "viewed") finish({
						outcome: "shown",
						provider: "google"
					});
					else if (info?.breakStatus === "frequencyCapped") finish({
						outcome: "skipped",
						provider: "google"
					});
					else finish({
						outcome: "unavailable",
						provider: "fallback_required"
					});
				}
			});
		} catch {
			finish({
				outcome: "unavailable",
				provider: "fallback_required"
			});
		}
	});
}
