async function redeemGlobalPromoCode(rawInput, alreadyAdFree) {
	const normalized = normalizePromoCode(rawInput);
	if (!normalized) return {
		ok: false,
		error: "Lütfen bir promosyon kodu gir."
	};
	const spec = GLOBAL_PROMO_CODES.find((p) => p.code === normalized);
	if (!spec) return {
		ok: false,
		error: "Geçersiz kod. Kodu kontrol edip tekrar dene."
	};
	if (spec.unlocksAdFree && spec.goldAmount === 0 && alreadyAdFree) return {
		ok: false,
		error: "Reklamsız sürüm hesabında zaten aktif; bu kodu başkası kullanabilir."
	};
	const user = auth.currentUser;
	if (!user || !user.emailVerified) return {
		ok: false,
		requiresAuth: true,
		error: "Dünya genelinde tek kullanımlık kodları doğrulamak için Google hesabınla giriş yapmalısın."
	};
	if (typeof navigator !== "undefined" && navigator.onLine === false) return {
		ok: false,
		error: "Tek seferlik kod doğrulaması için internet bağlantısı gerekiyor."
	};
	const path = `promo_redemptions/${spec.code}`;
	const promoRef = doc(db, "promo_redemptions", spec.code);
	try {
		await runTransaction(db, async (tx) => {
			if ((await tx.get(promoRef)).exists()) throw new Error("PROMO_ALREADY_REDEEMED");
			tx.set(promoRef, {
				codeId: spec.code,
				rewardType: spec.rewardType,
				redeemedByUid: user.uid,
				redeemedAt: serverTimestamp()
			});
		});
		return {
			ok: true,
			spec
		};
	} catch (error) {
		const msg = error instanceof Error ? error.message : String(error);
		const code = typeof error === "object" && error !== null && "code" in error ? String(error.code ?? "") : "";
		if (msg === "PROMO_ALREADY_REDEEMED") return {
			ok: false,
			error: "Bu tek seferlik kod daha önce kullanıldı ve artık geçersiz."
		};
		if (code.includes("permission-denied") || msg.toLowerCase().includes("permission")) {
			try {
				if ((await getDocFromServer(promoRef)).exists()) return {
					ok: false,
					error: "Bu tek seferlik kod daha önce kullanıldı ve artık geçersiz."
				};
			} catch {}
			try {
				handleFirestoreError(error, OperationType.CREATE, path);
			} catch {}
			return {
				ok: false,
				error: "Kod doğrulama izni reddedildi. Lütfen hesabınla yeniden giriş yap."
			};
		}
		if (code.includes("unavailable") || code.includes("failed-precondition") || msg.toLowerCase().includes("offline") || msg.toLowerCase().includes("network")) return {
			ok: false,
			error: "Sunucuya ulaşılamadı. İnternet bağlantını kontrol edip tekrar dene."
		};
		return {
			ok: false,
			error: "Kod doğrulanırken bir hata oluştu. Lütfen tekrar dene."
		};
	}
}
